--
-- Persisted monitor inventory snapshot — Project + Monitor rows only
-- (no Settings/API key, no User/Session, no ScheduleBlock — this is purely
-- the "which Promptwatch monitor IDs do we know about" inventory).
--
-- Captured 2026-09-04: 5 projects, 25 monitors (including inactive ones —
-- Promptwatch's own /monitors list endpoint only returns active monitors,
-- so this snapshot exists precisely so a fresh deploy doesn't have to
-- rediscover inactive monitors from scratch via that endpoint).
--
-- HOW TO APPLY on a fresh deploy, after `prisma db push` has created the
-- schema but before (or after) the app's first Sync:
--   psql "$DATABASE_URL" -f db/seed/monitors-seed.sql
-- or, running against the Docker Compose db service:
--   docker compose exec -T db psql -U promptwatch -d promptwatch -f - < db/seed/monitors-seed.sql
--
-- Safe to run more than once (every INSERT is ON CONFLICT (id) DO NOTHING)
-- and safe to run before or after Sync — it only fills in rows that don't
-- already exist; it never overwrites what a real Sync has already fetched.
--
-- This is a snapshot of active/inactive status at capture time, not a live
-- feed — run Sync in the app afterward (or just wait for the worker's next
-- tick) to refresh every monitor's current state from Promptwatch itself.
--

BEGIN;

SET statement_timeout = 0;
SET lock_timeout = 0;
SET idle_in_transaction_session_timeout = 0;
SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;
SELECT pg_catalog.set_config('search_path', '', false);
SET check_function_bodies = false;
SET xmloption = content;
SET client_min_messages = warning;
SET row_security = off;

